CREATE TEXT SEARCH DICTIONARY idn_syn
  (TEMPLATE = synonym, SYNONYMS = idn);
CREATE TEXT SEARCH DICTIONARY idn_stop
  (TEMPLATE = simple,
   STOPWORDS = indonesia);
CREATE TEXT SEARCH CONFIGURATION idn
  (COPY = simple);
ALTER TEXT SEARCH CONFIGURATION idn
  ALTER MAPPING FOR asciiword, word
  WITH idn_syn, idn_stop;

ALTER TABLE artikel ADD COLUMN tsv
 tsvector GENERATED ALWAYS AS (
  setweight(to_tsvector('idn',
   coalesce(judul,'')), 'A') ||
  setweight(to_tsvector('idn',
   coalesce(isi,'')), 'D')
 ) STORED;
CREATE INDEX artikel_tsv
  ON artikel USING GIN (tsv);

import html

def aman(cuplikan):
    t = html.escape(cuplikan)
    t = t.replace("[[[", "<mark>")
    return t.replace("]]]", "</mark>")

